CREATE VIEW v88107 AS SELECT *, 1 + NTH_VALUE(SUM(x3.v88037 / x5.v87525), 1) OVER (ORDER BY x5.v87525) AS x1, LAG(x5.v87525, 1, x5.v87525 * x5.v87525) OVER (ORDER BY x3.v88035 DESC, x3.v88035 ASC ROWS BETWEEN CURRENT ROW AND 2 FOLLOWING) AS x2 FROM v88034 AS x3, v87524 AS x5 WHERE x5.v87525 < 45.34e-306